import{_ as a,o as t,c as e,az as s}from"./chunks/framework.DXXa9EJF.js";const c=JSON.parse('{"title":"Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"guide/authentication.md","filePath":"guide/authentication.md"}'),n={name:"guide/authentication.md"};function h(r,i,o,d,l,p){return t(),e("div",null,[...i[0]||(i[0]=[s(`<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h1><p>ImagenHub uses two authentication methods depending on the context.</p><h2 id="api-key-authentication" tabindex="-1">API Key Authentication <a class="header-anchor" href="#api-key-authentication" aria-label="Permalink to “API Key Authentication”">​</a></h2><p>For programmatic access, use Bearer token authentication with your API key:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer sk_live_YOUR_KEY&quot;</span></span></code></pre></div><p>API keys come in two types:</p><table tabindex="0"><thead><tr><th>Type</th><th>Prefix</th><th>Purpose</th></tr></thead><tbody><tr><td>Live</td><td><code>sk_live_</code></td><td>Production use, credits are deducted</td></tr><tr><td>Test</td><td><code>sk_test_</code></td><td>Testing, no charges applied</td></tr></tbody></table><p>Create and manage API keys from the <a href="https://imagenhub.ai" target="_blank" rel="noreferrer">dashboard</a> or via the API keys endpoints (JWT auth required).</p><h3 id="endpoints-that-accept-api-keys" tabindex="-1">Endpoints that accept API keys <a class="header-anchor" href="#endpoints-that-accept-api-keys" aria-label="Permalink to “Endpoints that accept API keys”">​</a></h3><p>Most public-facing endpoints use API key auth: <code>/ping</code>, <code>/process</code>, <code>/tasks/*</code>, <code>/providers</code>, <code>/analytics/*</code>.</p><h2 id="jwt-authentication" tabindex="-1">JWT Authentication <a class="header-anchor" href="#jwt-authentication" aria-label="Permalink to “JWT Authentication”">​</a></h2><p>JWT tokens are used for dashboard and management operations — creating templates, managing API keys, and account settings.</p><h3 id="login" tabindex="-1">Login <a class="header-anchor" href="#login" aria-label="Permalink to “Login”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/auth/login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{ &quot;email&quot;: &quot;you@example.com&quot;, &quot;password&quot;: &quot;your-password&quot; }&#39;</span></span></code></pre></div><p>The response includes a Bearer JWT token. Include it in subsequent requests:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/templates</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer eyJhbGciOi...&quot;</span></span></code></pre></div><h3 id="token-refresh" tabindex="-1">Token refresh <a class="header-anchor" href="#token-refresh" aria-label="Permalink to “Token refresh”">​</a></h3><p>JWT tokens expire. Use the refresh endpoint to get a new token:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/auth/refresh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer eyJhbGciOi...&quot;</span></span></code></pre></div><h2 id="oauth" tabindex="-1">OAuth <a class="header-anchor" href="#oauth" aria-label="Permalink to “OAuth”">​</a></h2><p>ImagenHub also supports OAuth login via Google, GitHub, and other providers. Redirect users to:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /auth/{provider}</span></span></code></pre></div><p>After authentication, the callback at <code>/auth/{provider}/callback</code> issues a JWT token.</p><h2 id="error-responses" tabindex="-1">Error responses <a class="header-anchor" href="#error-responses" aria-label="Permalink to “Error responses”">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>401</code></td><td>Missing or invalid authentication credentials</td></tr><tr><td><code>402</code></td><td>Credit limit exceeded — top up or wait for reset</td></tr><tr><td><code>429</code></td><td>Rate limited (free tier) — check <code>Retry-After</code> header</td></tr></tbody></table>`,25)])])}const u=a(n,[["render",h]]);export{c as __pageData,u as default};
